<?php
/** Main local only: verify commercial history and explicitly allow additive image metadata. */
if(!defined('WP_CLI') || !WP_CLI || wp_get_environment_type()!=='local' || untrailingslashit(home_url())!=='http://localhost:8080'){exit(1);}
global $wpdb;$file='/backups/h9-media-preservation.json';$mode=$args[0]??'verify';
$capture=static function()use($wpdb){$out=[];foreach(['users','usermeta','wc_orders','wc_order_addresses','wc_orders_meta','woocommerce_order_items','woocommerce_order_itemmeta','commerce_legal_requests','commerce_legal_events'] as $suffix){$table=$wpdb->prefix.$suffix;$columns=$wpdb->get_col("SHOW COLUMNS FROM `$table`");$out[$suffix]=hash('sha256',wp_json_encode($wpdb->get_results("SELECT * FROM `$table` ORDER BY `".$columns[0].'`',ARRAY_A)));}
$out['posts']=hash('sha256',wp_json_encode($wpdb->get_results("SELECT * FROM {$wpdb->posts} ORDER BY ID",ARRAY_A)));
$out['non_attachment_meta']=hash('sha256',wp_json_encode($wpdb->get_results("SELECT m.* FROM {$wpdb->postmeta} m INNER JOIN {$wpdb->posts} p ON p.ID=m.post_id WHERE p.post_type<>'attachment' ORDER BY m.meta_id",ARRAY_A)));return $out;};
if($mode==='snapshot'){if(file_exists($file)){WP_CLI::error('Preservation baseline must not be overwritten');}$images=[];foreach(get_posts(['post_type'=>'attachment','posts_per_page'=>-1,'post_status'=>'inherit','fields'=>'ids']) as $id){$path=get_attached_file($id);$images[$id]=['meta'=>wp_get_attachment_metadata($id),'sha256'=>is_file($path)?hash_file('sha256',$path):null];}file_put_contents($file,wp_json_encode(['commerce'=>$capture(),'images'=>$images]));echo "Private commerce/media baseline saved.\n";return;}
$before=json_decode(file_get_contents($file),true);$now=$capture();$checks=[];foreach($before['commerce'] as $table=>$hash){$checks[$table]=hash_equals($hash,$now[$table]);}$unchanged=true;$additions=0;
foreach($before['images'] as $id=>$proof){$meta=wp_get_attachment_metadata($id);if(isset($meta['sizes']['commerce-card'])&&!isset($proof['meta']['sizes']['commerce-card'])){$additions++;unset($meta['sizes']['commerce-card']);}$path=get_attached_file($id);$unchanged=$unchanged&&wp_json_encode($meta)===wp_json_encode($proof['meta'])&&(!is_file($path)||hash_file('sha256',$path)===$proof['sha256']);}
$checks['original_images_and_existing_metadata']=$unchanged;echo wp_json_encode(['result'=>in_array(false,$checks,true)?'failed':'passed','checks'=>$checks,'additive_card_sizes'=>$additions],JSON_PRETTY_PRINT)."\n";if(in_array(false,$checks,true)){exit(1);}
